-- 154: Original BrillaPrep WASSCE BrillaPrep transitional Electronics beta content blueprint questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_154_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_154_guard;
INSERT INTO _migration_154_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_016' AND NOT (q.topic_id IS 'topic_was_electronics_b002_4' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'When is a silicon p-n junction diode forward biased?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Its n-side is made positive relative to its p-side","B. Both sides are held at the same potential","C. Its p-side is connected through reverse breakdown only","D. Its p-side is made positive relative to its n-side"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Forward bias reduces the junction barrier and permits substantial current after the applied voltage reaches the device’s operating region. Therefore the correct answer is D: Its p-side is made positive relative to its n-side.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_016' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_154_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_017' AND NOT (q.topic_id IS 'topic_was_electronics_b002_4' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the output of an ideal full-wave rectifier before filtering?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Unidirectional pulses during both input half-cycles","B. Unidirectional pulses during one input half-cycle only","C. A sinusoid that still alternates about zero","D. A constant DC level with no ripple"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Full-wave rectification reverses the negative half-cycle so load current has one direction on both halves of the AC input. Therefore the correct answer is A: Unidirectional pulses during both input half-cycles.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_017' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_154_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_018' AND NOT (q.topic_id IS 'topic_was_electronics_b002_4' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the role of a reservoir capacitor after a rectifier?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Raise the rectifier frequency before the transformer","B. Reduce ripple by supplying the load between waveform peaks","C. Hold the output at an exact value under every load","D. Block all direct current from reaching the load"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The capacitor charges near rectified peaks and discharges into the load between them, smoothing the pulsating voltage. Therefore the correct answer is B: Reduce ripple by supplying the load between waveform peaks.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_018' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_154_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_019' AND NOT (q.topic_id IS 'topic_was_electronics_b002_4' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a Zener diode useful in a simple voltage regulator?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It maintains a constant forward voltage at any current","B. It removes ripple without a series current-limiting element","C. It maintains an approximately constant reverse voltage in breakdown","D. It increases transformer secondary voltage in breakdown"]' AND q.correct_answer IS 'C' AND q.explanation IS 'A correctly biased Zener operates in controlled reverse breakdown, providing a reference or shunt-regulated voltage with current limiting. Therefore the correct answer is C: It maintains an approximately constant reverse voltage in breakdown.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_019' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_154_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_020' AND NOT (q.topic_id IS 'topic_was_electronics_b002_4' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A bridge rectifier has one diode open-circuit. What is a likely output symptom?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Normal full-wave output with slightly lower peak voltage","B. Zero output on both input half-cycles","C. Normal output voltage with half the ripple frequency","D. Reduced output with half-wave-like ripple"]' AND q.correct_answer IS 'D' AND q.explanation IS 'An open bridge diode removes one conduction path, so only part of the AC cycle reaches the load and ripple increases. Therefore the correct answer is D: Reduced output with half-wave-like ripple.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_020' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
